"""Generate Michigan's edition from shared UI and independently reviewed state data."""
import copy
import json
import re
from pa_edition import BASE, replace_line


def michigan_resources(root, ohio):
    ids = json.loads((root / 'data/public/federal-resource-ids.json').read_text())
    by_id = {r['program_id']: r for r in ohio}
    shared = []
    for id in ids:
        r = copy.deepcopy(by_id[id])
        r.update(service_area=['National'], state='shared')
        shared.append(r)
    return (shared + json.loads((root / 'data/public/mi-programs.json').read_text())
            + json.loads((root / 'data/public/mi-regional-referrals.json').read_text()))


def make_mi(html, resources, counties):
    html = replace_line(html, 'const DATA=', 'const DATA=[];')
    html = replace_line(html, 'const COUNTIES=', 'const COUNTIES=[];')
    html = html.replace('Ohio', 'Michigan').replace('All 88', 'All 83').replace('all 88', 'all 83')
    html = html.replace('<option value="OH">Michigan</option>', '<option value="OH">Ohio</option>')
    html = html.replace('Choose an Michigan county', 'Choose a Michigan county')
    html = html.replace("const STATE='OH';", "const STATE='MI';")
    html = replace_line(html, 'const national=', "const national=a=>['statewide','national','federal'].includes(a.toLowerCase());")
    html = html.replace('href="' + BASE + '"', 'href="' + BASE + 'mi.html"').replace('property="og:url" content="' + BASE + '"', 'property="og:url" content="' + BASE + 'mi.html"')
    html = html.replace('assets/share-preview.png', 'assets/vhg-logo.png').replace('content="1200"', 'content="715"').replace('content="630"', 'content="715"')
    html = html.replace('href="share.html"', 'href="share-mi.html"')
    html = html.replace('href="prototype-data.json"', 'href="data/public/michigan-resources.json"').replace('href="data/public/ohio-county-veterans-offices.json"', 'href="data/public/michigan-county-veterans-offices.json"')
    html = html.replace('county veterans offices', 'county veterans referrals').replace('county veterans office', 'veterans referral contact')
    html = html.replace('Browse contacts for all 83 county veterans referrals', 'Browse veterans referral contacts for all 83 counties')
    html = html.replace('Most phones come from Michigan AMVETS’ 2025–2026 directory.', 'County contacts use the Michigan Association of County Veteran Counselors public directory and official county or provider pages. Ionia uses a clearly labeled MVAA statewide referral.')
    html = html.replace('Statewide edition · Updated', 'Michigan edition · Updated')
    html = html.replace('Michigan’s waiver rule specifies proposal and approval requirements; VA and other funders have their own processes.', 'Ask your Michigan supports coordinator or funding administrator about assessment, written approval, owner consent and accepted providers.')
    html = html.replace('https://codes.ohio.gov/ohio-administrative-code/rule-5160-44-13', 'https://www.michigan.gov/mdhhs/assistance-programs/healthcare/seniors/michoicewaiver/mi-choice-waiver-program-Use').replace('Michigan home modification authorization and provider rules', 'Michigan MI Choice services and waiver agencies')
    html = re.sub(r'<div class="coverage notice">.*?</div>', '<div class="coverage notice"><strong>Michigan coverage:</strong> Veterans referral routes and matched aging contacts for all 83 counties. County veterans numbers come from the counselors’ association directory and official agency pages; Ionia uses a clearly labeled MVAA statewide referral. Wayne County aging services divide by city: both agencies and their boundaries are shown. Ombudsman support uses statewide routing. Local posts, repair providers and funding availability are still being researched.</div>', html, count=1)
    priority = ['mi-claims','mi-options','mi-aging','mi-choice','mi-homehelp','mi-ship','mi-ombudsman','mi-at','mi-emergency','r02-aid-attendance-housebound','r02-va-pension','r02-survivors-pension','r02-va-health-enrollment','va-accredited-help']
    routes = dict(
        benefits=['r02-aid-attendance-housebound','r02-va-pension','r02-disability-increase','r02-pension-medicaid-rule','r02-survivors-pension','r02-dic','mi-claims','mi-ship','mi-emergency','va-accredited-help'],
        survivors=['r02-survivors-pension','r02-dic','r02-aid-attendance-housebound','r02-va-burial','mi-claims','va-accredited-help','nara-discharge-records'],
        care=['r02-va-health-enrollment','va-location-finder','r02-va-cnh','r02-va-clc','r02-general-caregiver','r02-family-caregiver','r02-hospice','r02-palliative','mi-choice','mi-homehelp','mi-pace','mi-caregiver'],
        rights=['mi-ombudsman','mi-rights','mi-options'],
        local=['mi-options','mi-aging','mi-choice','mi-homehelp','mi-caregiver','mi-at','mi-pace'],
        housing=['va-housing-help','nara-discharge-records','va-location-finder','va-accredited-help','mi-emergency','mi-options'])
    topics = dict(daily=['mi-options','mi-aging','mi-choice','mi-homehelp','mi-pace','mi-caregiver'],accessibility=['mi-options','mi-choice','mi-at','mi-rights'],vision=['mi-blind','mi-at'],hearing=['mi-relay','mi-at'],memory=['alz-dementia-support','mi-caregiver','mi-options'],costs=['mi-ship','mi-options','mi-choice','mi-homehelp'],rights=['mi-rights','mi-ombudsman','mi-options'])
    for name,value in [('priority',priority),('routes',routes),('seniorTopics',topics)]:
        html = replace_line(html, 'const '+name+'=', 'const '+name+'='+json.dumps(value)+';')
    html = replace_line(html, 'routes.accessibility=', "routes.accessibility=['va-hisa','va-sah','va-sha','va-tra','mi-choice','mi-at','mi-options','mi-emergency','mi-rights','va-location-finder',...DATA.filter(x=>x.regional_role==='aging_agency').map(x=>x.program_id)];")
    html = replace_line(html, 'routes.seniors=', "routes.seniors=[...new Set(Object.values(seniorTopics).flat()),...DATA.filter(x=>x.regional_role).map(x=>x.program_id),'cms-care-compare'];")
    for prefix,text in [('function officeCard(',OFFICE_JS),('function renderOfficeList()',OFFICE_LIST_JS),('function renderCounty()',COUNTY_JS),('function renderSeniorGuide()',SENIOR_JS),('function renderAccessibility()',ACCESS_JS),('function audience(',AUDIENCE_JS)]:
        html = replace_line(html, prefix, text)
    html = html.replace(OFFICE_JS, AGING_JS+'\n'+OFFICE_JS)
    for name,value in [('DATA',resources),('COUNTIES',counties)]:
        html = replace_line(html, 'const '+name+'=', 'const '+name+'='+json.dumps(value,ensure_ascii=True).replace('<','\\u003c')+';')
    return html

AGING_JS = """function agingContactsHTML(county){const agencies=DATA.filter(x=>x.regional_role==='aging_agency'&&x.service_area.includes(county));return agencies.length?(agencies.length>1?'<p><strong>Wayne County: choose the agency for the resident’s city.</strong></p>':'')+agencies.map(x=>'<p><strong>'+esc(x.organization)+'</strong><br>'+phoneLink(x.public_contact.phone)+'</p>'+(x.service_scope?'<p class="small">'+esc(x.service_scope)+'</p>':'')+'<p class="meta"><a href="'+esc(x.official_url)+'" target="_blank" rel="noopener">Aging contact source</a> · '+esc(labels[x.verification.record_status])+' · '+esc(x.verification.last_reviewed_on)+'</p>').join(''):'<p>Choose a county above for matched aging contacts.</p>'}"""
OFFICE_JS = """function officeCard(c){return `<article class="office-card"><span class="badge">${c.office_type==='state'?'MVAA statewide referral':'County veterans contact'}</span><h2>${esc(c.county)} County</h2><p><strong>${esc(c.organization)}</strong><br>${phoneLink(c.phone)}</p><p>Ask for benefits screening and claims referral support. Confirm which accredited representative serves the county and ask about remote appointments.</p>${c.note?'<p class="small">'+esc(c.note)+'</p>':''}<p class="meta">${c.contact_status==='official_website'?'Phone published on an official agency website':'Phone published in the county counselors’ association directory'} · Reviewed ${esc(c.reviewed_on)}</p><div class="links"><a href="${esc(sourceURL(c))}" target="_blank" rel="noopener noreferrer">Contact source ↗</a></div></article>`}"""
OFFICE_LIST_JS = """function renderOfficeList(){const q=$('office-search').value.toLowerCase().trim();const rows=COUNTIES.filter(c=>c.county.toLowerCase().includes(q));$('office-list').innerHTML=rows.map(c=>`<div class="office-row"><button data-county="${esc(c.county)}">${esc(c.county)} County</button>${phoneLink(c.phone)}<p>${c.office_type==='state'?'MVAA statewide referral · ':''}<a href="${esc(sourceURL(c))}" target="_blank" rel="noopener noreferrer">${c.contact_status==='official_website'?'Official agency source':'County counselors’ directory source'} ↗</a></p></div>`).join('')||'<p>No matching county. Try a shorter name.</p>';document.querySelectorAll('[data-county]').forEach(b=>b.onclick=()=>{$('county').value=b.dataset.county;render();$('county-start').scrollIntoView({behavior:'smooth'})})}"""
COUNTY_JS = """function renderCounty(){$('print-handoff-status').textContent='';const c=COUNTIES.find(c=>c.county===$('county').value);$('print-county').textContent=c?c.county+' County, Michigan':'Michigan statewide resources';if(!c){$('county-panel').innerHTML='<p class="meta">Choose a county for veterans referral help, matched aging contacts, statewide ombudsman routing and a printable handoff.</p>';return}$('county-panel').innerHTML='<div class="contact-grid">'+officeCard(c)+'<article><h2>More help in '+esc(c.county)+' County</h2><h3>Aging and community support</h3>'+agingContactsHTML(c.county)+'<p>Ask about meals, transport, caregiving and support at home. Military service is not required.</p><h3>Statewide ombudsman routing</h3><p>'+phoneLink('866-485-9393')+'</p><p>Give the facility county and ask for the local ombudsman. For immediate danger, call 911.</p><p><a href="'+esc(DATA.find(x=>x.program_id==='mi-ombudsman').official_url)+'" target="_blank" rel="noopener">Official ombudsman contact source</a></p><h3>MI Options: care and Medicare counseling</h3><p>'+phoneLink('800-803-7174')+'</p><p class="meta">Ask about intake, eligibility and availability when you call.</p></article></div>'}"""
SENIOR_JS = """function renderSeniorGuide(){const active=route==='seniors';$('seniors-guide').hidden=!active;$('community-guide').hidden=route!=='community';$('county-panel').hidden=['accessibility','seniors','community'].includes(route);if(active){$('county-title').textContent='Choose your Michigan county';$('county-intro').textContent='Find your regional aging contact and MI Options counseling. Military service is not required.'}if(route==='community'){$('county-title').textContent='Find Michigan community connections';$('county-intro').textContent='Use official post locators while local post contacts are being researched.'}if(!active)return;const county=$('county').value;$('seniors-contact').innerHTML='<h3>Start with MI Options or your aging agency</h3><p><strong>MI Options: statewide care and Medicare counseling</strong><br>'+phoneLink('800-803-7174')+'</p>'+agingContactsHTML(county)+'<p>Describe the daily-living need and ask for assessment and the next referral. Aging and Medicaid programs have separate eligibility requirements.</p>';const topic=$('senior-topic').value;const guidance={daily:'Ask about meals, transport, personal care and caregiver support. Ask the local MDHHS Adult Services unit about Home Help assessment, or a waiver agency about MI Choice screening.',accessibility:'Describe the access barrier. Ask about MI Choice assessment and environmental accessibility adaptations. MATP offers device trials and loans; it does not perform clinical assessments or guarantee permanent equipment funding.',vision:'Ask the Bureau of Services for Blind Persons about independent living services for residents age 55+ with qualifying vision loss. Assessment and equipment budget limits apply.',hearing:'Dial 711 for Michigan Relay. Ask MATP about communication-device demonstrations and loans. These routes do not guarantee hearing-aid funding.',memory:'Contact the Alzheimer’s Association for dementia support. Ask about Creating Confident Caregivers classes, respite and services at home; seek clinical evaluation for new memory concerns.',costs:'Michigan SHIP offers free Medicare counseling through MI Options. Ask about savings programs, coverage and local care options. Medicaid support requires separate screening.',rights:'Contact the long-term-care ombudsman for facility resident concerns and Disability Rights Michigan for disability access and rights. Confirm intake priorities and the follow-up process.'};$('senior-guidance').innerHTML='<strong>'+(topic?'Your next step':'Choose a need, then make a referral')+'</strong><p>'+esc(guidance[topic]||'Choose a need to narrow the referrals. Military service is not required for these routes. Confirm eligibility and availability with the provider.')+'</p>'}"""
AUDIENCE_JS = """function audience(x){if(/survivors|r02-dic/.test(x.program_id))return 'Surviving spouses and other qualifying survivors';if(/aid-attendance/.test(x.program_id))return 'Qualifying veterans and survivors who need daily help';if(x.program_id==='mi-blind')return 'Michigan residents age 55+ with qualifying vision loss';if(x.program_id==='mi-pace')return 'Adults age 55+ in a participating PACE service area';if(/ombudsman/.test(x.program_id))return 'Residents of nursing homes, homes for the aged and adult foster care facilities';if(/nara/.test(x.program_id))return 'Veterans and eligible records requesters';return null}"""
ACCESS_JS = """function renderAccessibility(){const active=route==='accessibility';$('accessibility-guide').hidden=!active;$('county-panel').hidden=active;$('county-title').textContent=active?'Choose where help is needed':'Your first local contact';$('county-intro').textContent=active?'Choose a Michigan county for regional referral contacts.':'Veterans contacts can help with benefits and referral screening. Confirm which county should handle a resident who recently moved.';if(!active)return;const veteran=$('access-veteran').value,home=$('access-home').value,coverage=$('access-waiver').value,county=$('county').value,office=COUNTIES.find(c=>c.county===county),va=veteran==='yes',newHome=home==='new';const primary=coverage==='waiver'?'Your supports coordinator':va?(newHome?'VA adapted housing team':'VA Prosthetics and your care team'):'MI Options: aging and disability counseling';const action=coverage==='waiver'?'Ask for an access assessment and written authorization through your service plan.':va?(newHome?'Ask about SAH/SHA eligibility and housing project review. HISA excludes new construction.':'Ask for clinical review and the HISA application process.'):'Ask which local agency can assess the barrier and screen for Michigan support.';const contact=coverage==='waiver'?'<p>Use your coordinator’s direct number. Ask which program can authorize the proposed change.</p>':va?'<p><a class="contact-action" href="https://www.va.gov/find-locations/?facilityType='+(newHome?'benefits':'health')+'" target="_blank" rel="noopener">Find your VA '+(newHome?'benefits office':'medical facility')+'</a></p>':'<p>'+phoneLink('800-803-7174')+'</p>';$('access-first').innerHTML='<article class="first-call"><span class="badge">Start here'+(county?' · '+esc(county)+' County, MI':'')+'</span><h3>'+esc(primary)+'</h3><p>'+esc(action)+'</p>'+contact+'</article><article><h3>Need help getting connected?</h3>'+(office?'<p><strong>'+esc(office.organization)+'</strong><br>'+phoneLink(office.phone)+'</p>'+(office.office_type==='state'?'<p class="small">MVAA statewide referral: ask for an accredited representative serving your county.</p>':''):'<p>Choose a county above for veterans referral help.</p>')+agingContactsHTML(county)+'<p><strong>MI Options statewide routing</strong><br>'+phoneLink('800-803-7174')+'</p></article>';$('access-steps').innerHTML='<h3>Your next three steps</h3><ol><li><strong>Make the first call.</strong> '+esc(action)+' Ask who handles follow-up.</li><li><strong>Prepare requested documents.</strong> '+(va&&!newHome&&coverage!=='waiver'?'For HISA, gather the prescription, Form 10-0103, owner permission, itemized estimate and before photograph. <a href="#hisa-checklist" id="open-hisa">Open the HISA checklist</a>.':'Ask about assessment, disability documentation, residency, income, owner consent and estimate requirements.')+'</li><li><strong>Confirm approval and remaining costs.</strong> Ask who approves work, which providers are accepted and how uncovered costs are handled.</li></ol>';const box=(title,body)=>'<article><h3>'+title+'</h3>'+body+'</article>';const parts=[];if(veteran!=='no'){parts.push(box('Veteran route: VA clinical review','<p>Ask Prosthetic and Sensory Aids Service about HISA. HISA excludes new construction; SAH/SHA have separate qualifying disability and ownership rules.</p><p><a href="https://www.va.gov/find-locations/?facilityType=health" target="_blank" rel="noopener">Find your VA medical facility</a></p>'));parts.push(box('Michigan veteran emergency support','<p>Ask MVAA '+phoneLink('800-642-4838')+' about emergency assistance and county relief funds. The Veterans Trust Fund has separate service and financial-crisis requirements; a referral does not establish repair funding.</p>'));if(home==='family')parts.push(box('Temporary family home: ask about TRA','<p>Ask VA whether TRA applies; it requires SAH or SHA eligibility and temporary residence in a family member’s home.</p>'))}parts.push(box('Michigan: assessment and supports coordination','<p>MI Options '+phoneLink('800-803-7174')+' can connect you to local care counseling. MI Choice includes environmental accessibility adaptations for eligible participants. Ask a waiver agency about assessment and authorization. Home Help pays for approved personal assistance and excludes home repairs.</p>'));parts.push(box('Equipment demonstrations and loans','<p>Contact Michigan Assistive Technology Program '+phoneLink('800-578-0280')+' about trials and device loans. MATP does not provide clinical assessments. Equipment stock, permanent ramps, installation and funding are not guaranteed.</p>'));if(coverage==='waiver')parts.push(box('Coordinate with your service plan','<p>Ask your supports coordinator what can be authorized through your plan. Medicaid enrollment alone does not establish modification coverage.</p>'));if(home==='new')parts.push(box('Unfinished or new construction','<p>HISA excludes new construction. Ask each administrator whether the proposed work qualifies before requesting estimates or committing funds.</p>'));if(home==='facility')parts.push(box('Returning home: coordinate before discharge','<p>Ask the discharge planner and a MI Choice waiver agency about assessment, care needs and a safe community transition plan. A referral does not guarantee enrollment or a home modification.</p>'));if(home==='rent')parts.push(box('Rented home: confirm owner responsibilities','<p>Arrange owner permission and clarify any existing duty to provide accessibility changes. HISA requires notarized owner permission for renters; other programs have their own rules.</p>'));$('access-routing').innerHTML=parts.join('');const checklistLink=$('open-hisa');if(checklistLink)checklistLink.onclick=()=>{$('hisa-checklist').open=true};}"""
